(function(){function drawLine(ctx,labels,data){const w=ctx.canvas.width,h=ctx.canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#e5e7eb';ctx.beginPath();ctx.moveTo(40,10);ctx.lineTo(40,h-30);ctx.lineTo(w-10,h-30);ctx.stroke();if(data.length===0)return;const max=Math.max.apply(null,data),min=Math.min.apply(null,data);const range=max-min||1;ctx.strokeStyle='#2563eb';ctx.beginPath();data.forEach((v,i)=>{const x=40+(i/(data.length-1||1))*(w-60);const y=(h-30)-((v-min)/range)*(h-50);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();ctx.fillStyle='#111';ctx.font='10px sans-serif';labels.forEach((l,i)=>{const x=40+(i/(labels.length-1||1))*(w-60);ctx.fillText(l,x-10,h-12);});}window.Chart=function(ctx,opts){const c=ctx.getContext('2d');drawLine(c,opts.data.labels,opts.data.datasets[0].data);};})();
